using System.Collections.Immutable;
using System.Text;
using Dungeon.Core;
using Dungeon.Core.Content;

namespace Dungeon.Sim.Tools;

/// <summary>
/// Writes <c>src/Core/Random/StreamHandles.g.cs</c>, the typed stream handles of <c>registry/streams.json</c> (owner
/// ruling: generated by a Sim command and drift-tested, like <c>ContentHashes.g.cs</c>). Run
/// <c>dotnet run --project src/Sim -- stream-handles</c> after every <c>streams.json</c> edit; <c>StreamHandlesTests</c>
/// fails until the file matches.
/// </summary>
/// <remarks>
/// One <c>readonly record struct</c> per non-domain row, named by the PascalCase concatenation of its chain's labels
/// plus <c>Key</c> (<c>h:</c> written <c>H</c>; <c>:</c>, <c>.</c> and <c>-</c> dropped, the next letter capitalized).
/// Each is marked <c>[StreamKey]</c> and holds the row's key in a get-only <c>Value</c> set by an internal constructor,
/// so only this file builds one (DUN012 reports any <c>new</c>, explicit <c>default</c> or <c>with</c> of it elsewhere
/// in Core). A drawn-from row (any class but <c>node</c> and <c>keyed</c>) also has a
/// <c>Handle</c> and an <c>Open()</c> that opens it at counter 0 (so no file outside this one calls
/// <c>DrawStream.Open</c>, DUN012), and each child row is one member: a single <c>KeyAlgebra.Derive</c> call, or for a keyed domain a
/// single <c>KeyAlgebra.H</c> call returning <c>ulong</c>. <c>Streams</c> holds the root rows, and
/// <c>StreamHandleIndex.All</c> and <c>StreamHandleIndex.Domains</c> call every non-domain row and every keyed domain
/// through the chain for the cross-check tests. Everything is
/// emitted in ordinal row-id order.
/// </remarks>
public static class StreamHandlesWriter
{
    /// <summary>The exact file text for the stream rows of <paramref name="set"/>: LF line endings and a trailing newline.</summary>
    /// <exception cref="ArgumentNullException"><paramref name="set"/> is null.</exception>
    /// <exception cref="InvalidOperationException">Two rows or two members would get one name, or a label or index name is no C# identifier.</exception>
    public static string Write(ContentSet set)
    {
        ArgumentNullException.ThrowIfNull(set);
        var rows = set.All<StreamRow>().Sort((a, b) => string.CompareOrdinal(a.Id, b.Id));
        var byId = rows.ToDictionary(r => r.Id, StringComparer.Ordinal);
        var stems = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var row in rows)
        {
            stems[row.Id] = Stem(row, byId);
        }

        var nonDomain = rows.Where(r => !StreamRegistry.IsDomain(set, r)).ToImmutableArray();
        var structNames = new HashSet<string>(StringComparer.Ordinal);
        foreach (var row in nonDomain)
        {
            if (!structNames.Add(stems[row.Id] + "Key"))
            {
                throw new InvalidOperationException($"\"{row.Id}\" gives the key struct {stems[row.Id]}Key a second time.");
            }
        }

        var sb = new StringBuilder();
        Line(sb, "// <auto-generated/>");
        Line(sb, "// Written by `dotnet run --project src/Sim -- stream-handles` from content/registry/streams.json. Do not edit.");
        Line(sb, "");
        Line(sb, "#nullable enable");
        Line(sb, "");
        Line(sb, "using System;");
        Line(sb, "using System.Collections.Immutable;");
        Line(sb, "");
        Line(sb, "namespace Dungeon.Core;");
        Line(sb, "");

        Line(sb, "/// <summary>The root stream keys of a run, one member per root row of <c>registry/streams.json</c> (SV 4.3).</summary>");
        Line(sb, "public static class Streams");
        Line(sb, "{");
        var roots = rows.Where(r => r.Parent is null).ToImmutableArray();
        Members(sb, set, roots, stems, "runSeed", root: true);
        Line(sb, "}");

        foreach (var row in nonDomain)
        {
            Line(sb, "");
            Line(sb, $"/// <summary>The key of <c>{row.Id}</c>.</summary>");
            Inert(sb, row, "");
            Line(sb, "[StreamKey]");
            Line(sb, $"public readonly record struct {stems[row.Id]}Key");
            Line(sb, "{");
            Line(sb, $"    internal {stems[row.Id]}Key(ulong value) => Value = value;");
            Line(sb, "");
            Line(sb, "    /// <summary>The key.</summary>");
            Line(sb, "    public ulong Value { get; }");
            Line(sb, "");
            var children = rows.Where(r => string.Equals(r.Parent, row.Id, StringComparison.Ordinal)).ToImmutableArray();
            var names = new HashSet<string>(StringComparer.Ordinal) { "Value" };
            bool drawn = row.Class is not (CountClass.Node or CountClass.Keyed);
            if (drawn)
            {
                names.Add("Handle");
                names.Add("Open");
                Line(sb, $"    /// <summary>The stream <c>{row.Id}</c>.</summary>");
                Line(sb, $"    public StreamHandle Handle => new(\"{row.Id}\", Value);");
                Line(sb, "");
                Line(sb, $"    /// <summary>Opens <c>{row.Id}</c> at counter 0 (DS15); the only way outside this file to open it (DUN012).</summary>");
                Line(sb, "    public DrawStream Open() => DrawStream.Open(Value);");
            }

            foreach (var child in children)
            {
                if (!names.Add(Pascal(child.Label)))
                {
                    throw new InvalidOperationException($"\"{child.Id}\" gives {stems[row.Id]}Key the member {Pascal(child.Label)} a second time.");
                }
            }

            if (drawn && children.Length > 0)
            {
                Line(sb, "");
            }

            if (!drawn && children.Length == 0)
            {
                // A node or keyed row with no children: drop the blank line after Value.
                sb.Length -= 1;
            }

            Members(sb, set, children, stems, "Value", root: false);
            Line(sb, "}");
        }

        Line(sb, "");
        Line(sb, "/// <summary>Every non-domain stream row called through its handle chain, for the <c>StreamRegistry.KeyOf</c> cross-check.</summary>");
        Line(sb, "internal static class StreamHandleIndex");
        Line(sb, "{");
        Line(sb, "    /// <summary>");
        Line(sb, "    /// One entry per non-domain row, in ordinal row-id order: the row id and its key for a run seed, the numeric indices");
        Line(sb, "    /// and the <c>labelId</c> texts along the chain, each in order.");
        Line(sb, "    /// </summary>");
        Line(sb, "    public static readonly ImmutableArray<(string RowId, Func<ulong, ulong[], string[], ulong> Key)> All =");
        Line(sb, "    [");
        foreach (var row in nonDomain)
        {
            Line(sb, $"        (\"{row.Id}\", (rs, u, t) => {Call(row, byId)}.Value),");
        }

        Line(sb, "    ];");
        Line(sb, "");
        Line(sb, "    /// <summary>");
        Line(sb, "    /// One entry per keyed domain, in ordinal row-id order: the row id and its <c>H</c> for a run seed, the numeric");
        Line(sb, "    /// indices and the <c>labelId</c> texts along the chain, each in order.");
        Line(sb, "    /// </summary>");
        Line(sb, "    public static readonly ImmutableArray<(string RowId, Func<ulong, ulong[], string[], ulong> H)> Domains =");
        Line(sb, "    [");
        foreach (var row in rows.Where(r => StreamRegistry.IsDomain(set, r)))
        {
            Line(sb, $"        (\"{row.Id}\", (rs, u, t) => {Call(row, byId, domain: true)}),");
        }

        Line(sb, "    ];");
        Line(sb, "}");
        return sb.ToString();
    }

    // One member per row of `members`, deriving from `source` (runSeed for a root, else the struct's Value).
    private static void Members(StringBuilder sb, ContentSet set, ImmutableArray<StreamRow> members, IReadOnlyDictionary<string, string> stems, string source, bool root)
    {
        string indent = "    ";
        for (int i = 0; i < members.Length; i++)
        {
            var row = members[i];
            if (i > 0)
            {
                Line(sb, "");
            }

            var parameters = new List<string>();
            var arguments = new List<string>();
            var parameterNames = new HashSet<string>(StringComparer.Ordinal);
            if (root)
            {
                parameters.Add("ulong runSeed");
                parameterNames.Add("runSeed");
            }

            foreach (var index in row.Indices)
            {
                string name = Camel(index.Name);
                if (!parameterNames.Add(name))
                {
                    throw new InvalidOperationException($"\"{row.Id}\" takes the parameter {name} twice.");
                }

                parameters.Add($"{TypeOf(index.Type)} {name}");
                arguments.Add(index.Type == IndexType.LabelId ? $"KeyAlgebra.LabelId({name})" : name);
            }

            string args = string.Concat(arguments.Select(a => ", " + a));
            string member = Pascal(row.Label);
            string modifiers = root ? "public static" : "public";
            if (StreamRegistry.IsDomain(set, row))
            {
                Line(sb, $"{indent}/// <summary>The keyed hash <c>{row.Id}</c>.</summary>");
                Inert(sb, row, indent);
                Line(sb, $"{indent}{modifiers} ulong {member}({string.Join(", ", parameters)}) => KeyAlgebra.H({source}, \"{row.Label}\"{args});");
                continue;
            }

            Line(sb, $"{indent}/// <summary>The key of <c>{row.Id}</c>.</summary>");
            Inert(sb, row, indent);
            string body = $"new(KeyAlgebra.Derive({source}, \"{row.Label}\"{args}))";
            Line(sb, parameters.Count == 0
                ? $"{indent}{modifiers} {stems[row.Id]}Key {member} => {body};"
                : $"{indent}{modifiers} {stems[row.Id]}Key {member}({string.Join(", ", parameters)}) => {body};");
        }
    }

    // The handle chain from Streams to `row`, with `u[i]` for the numeric and `t[i]` for the text indices; a domain's
    // last member is a method, so it is always called.
    private static string Call(StreamRow row, IReadOnlyDictionary<string, StreamRow> byId, bool domain = false)
    {
        var chain = new List<StreamRow>();
        for (StreamRow? r = row; r is not null; r = r.Parent is { } p ? byId[p] : null)
        {
            chain.Add(r);
        }

        chain.Reverse();
        var sb = new StringBuilder("Streams");
        int u = 0;
        int t = 0;
        foreach (var r in chain)
        {
            var arguments = new List<string>();
            if (r.Parent is null)
            {
                arguments.Add("rs");
            }

            foreach (var index in r.Indices)
            {
                arguments.Add(index.Type switch
                {
                    IndexType.LabelId => $"t[{t++}]",
                    IndexType.UInt => $"(uint)u[{u++}]",
                    _ => $"u[{u++}]",
                });
            }

            sb.Append('.').Append(Pascal(r.Label));
            if (arguments.Count > 0 || (domain && ReferenceEquals(r, row)))
            {
                sb.Append('(').Append(string.Join(", ", arguments)).Append(')');
            }
        }

        return sb.ToString();
    }

    private static void Inert(StringBuilder sb, StreamRow row, string indent)
    {
        if (row.IsInert)
        {
            Line(sb, $"{indent}/// <remarks>Inert until {row.Wave} (D-08): the DrawLedger expects 0 draws on it.</remarks>");
        }
    }

    private static string Stem(StreamRow row, IReadOnlyDictionary<string, StreamRow> byId)
    {
        var sb = new StringBuilder();
        for (StreamRow? r = row; r is not null; r = r.Parent is { } p ? byId[p] : null)
        {
            sb.Insert(0, Pascal(r.Label));
        }

        return sb.ToString();
    }

    private static string TypeOf(IndexType type) => type switch
    {
        IndexType.ULong => "ulong",
        IndexType.UInt => "uint",
        IndexType.LabelId => "string",
        _ => throw new ArgumentOutOfRangeException(nameof(type), type, "unknown index type."),
    };

    // A label in PascalCase: the first letter capitalized; ':', '.' and '-' dropped and the next letter capitalized.
    private static string Pascal(string label)
    {
        var sb = new StringBuilder(label.Length);
        bool upper = true;
        foreach (char c in label)
        {
            if (c is ':' or '.' or '-')
            {
                upper = true;
                continue;
            }

            sb.Append(upper && c is >= 'a' and <= 'z' ? (char)(c - 'a' + 'A') : c);
            upper = false;
        }

        return Identifier(sb.ToString(), label);
    }

    // An index name in camelCase: the first letter lowered (`N` becomes `n`).
    private static string Camel(string name)
    {
        char first = name[0] is >= 'A' and <= 'Z' ? (char)(name[0] - 'A' + 'a') : name[0];
        return Identifier(first + name.Substring(1), name);
    }

    private static string Identifier(string s, string from)
    {
        bool ok = s.Length > 0 && char.IsAsciiLetter(s[0]) && s.All(c => char.IsAsciiLetterOrDigit(c) || c == '_');
        return ok ? s : throw new InvalidOperationException($"\"{from}\" gives \"{s}\", which is not a C# identifier.");
    }

    private static void Line(StringBuilder sb, string text) => sb.Append(text).Append('\n');
}
